from pathlib import Path

def parse(p):
    d = {}
    for raw in Path(p).read_text().splitlines():
        line = raw.strip()
        if not line or line.startswith('#') or line.startswith(';'):
            continue
        if '=' not in line:
            continue
        k, v = line.split('=', 1)
        d[k.strip()] = v.strip()
    return d

f1 = "/data/v1.conf"
f2 = "/data/v2.conf"
a = parse(f1)
b = parse(f2)

added = {k: b[k] for k in b if k not in a}
removed = {k: a[k] for k in a if k not in b}
changed = {k: (a[k], b[k]) for k in a if k in b and a[k] != b[k]}
unchanged = {k: a[k] for k in a if k in b and a[k] == b[k]}

print(f"Comparison of {f1} vs {f2}")
print("=" * 50)
print()
if added:
    print(f"Added keys ({len(added)}) — present in v2 only:")
    for k in sorted(added):
        print(f"  + {k}={added[k]}")
else:
    print("Added keys: none")
print()
if removed:
    print(f"Removed keys ({len(removed)}) — present in v1 only:")
    for k in sorted(removed):
        print(f"  - {k}={removed[k]}")
else:
    print("Removed keys: none")
print()
if changed:
    print(f"Changed values ({len(changed)}):")
    for k in sorted(changed):
        old, new = changed[k]
        print(f"  ~ {k}: '{old}' -> '{new}'")
else:
    print("Changed values: none")
print()
if unchanged:
    print(f"Unchanged ({len(unchanged)}):")
    for k in sorted(unchanged):
        print(f"    {k}={unchanged[k]}")
print()
print(f"Summary: {len(added)} added, {len(removed)} removed, {len(changed)} changed, {len(unchanged)} unchanged.")
